// Design Token Creator — generated by the figma-design-tokens skill.
// Runs entirely inside Figma via the Plugin API: no MCP, no personal
// access token, no plan requirement (Variables via the Plugin API work
// on free plans — it's only the REST API's write endpoints that are
// plan-gated). Import once (Plugins -> Development -> Import plugin
// from manifest), then Run each time the TOKENS block below is updated.
//
// Never overwrites anything that already exists by name — existing
// primitives, semantics, or text styles are skipped and reported, not
// touched. Two Variable collections are created (or reused if already
// present): "Primitives" with a single mode, and a semantic collection
// (name below) with one mode per theme, where each semantic Variable
// aliases a Primitives Variable and that alias target can differ by mode.

/* === TOKENS (filled in per run by the skill — replace this whole block) === */
const TOKENS = {
  primitivesCollectionName: "Primitives",
  semanticCollectionName: "Colors",
  modes: ["Light"], // e.g. ["Light", "Dark"] if dark mode is in scope

  // Flat, mode-invariant. "blue/500": "#3b82f6"
  primitives: {},

  // aliasOf is either a single primitive name (same target in every mode)
  // or an object keyed by mode name if the target differs per mode, e.g.
  // "background/default": { aliasOf: { Light: "gray/50", Dark: "gray/900" } }
  semantics: {},

  // size/lineHeight in px, letterSpacing in em (fraction of size).
  // "heading/xl": { family: "Inter", style: "Bold", size: 40, lineHeight: 48, letterSpacing: -0.02 }
  textStyles: {},
};
/* === END TOKENS === */

function hexToRgb(hex, alpha = 1) {
  // COLOR variable values need {r,g,b,a} - unlike paint colors, which take
  // {r,g,b} with no alpha. Every token in this skill's scope is fully
  // opaque, so alpha defaults to 1 rather than being threaded through TOKENS.
  const h = hex.replace("#", "");
  const full = h.length === 3 ? h.split("").map((c) => c + c).join("") : h;
  const int = parseInt(full, 16);
  return {
    r: ((int >> 16) & 255) / 255,
    g: ((int >> 8) & 255) / 255,
    b: (int & 255) / 255,
    a: alpha,
  };
}

// Variables default to ALL_SCOPES, which is almost never what you want -
// it clutters every color picker in Figma with tokens that were never
// meant to be applied directly. Primitives are hidden entirely (nothing
// should pick them - only semantics alias them). Semantics get scoped to
// where their role actually applies, inferred from the token's name
// prefix; an unrecognized prefix falls back to ALL_FILLS (still explicit,
// just broad) rather than silently inheriting ALL_SCOPES.
function scopesForSemantic(name) {
  if (name.startsWith("background/")) return ["FRAME_FILL", "SHAPE_FILL"];
  if (name.startsWith("text/")) return ["TEXT_FILL"];
  if (name.startsWith("border/")) return ["STROKE_COLOR"];
  return ["ALL_FILLS"];
}

async function getOrCreateCollection(name, modeNames) {
  const collections = await figma.variables.getLocalVariableCollectionsAsync();
  let collection = collections.find((c) => c.name === name);
  if (!collection) {
    collection = figma.variables.createVariableCollection(name);
    collection.renameMode(collection.modes[0].modeId, modeNames[0]);
    for (let i = 1; i < modeNames.length; i++) collection.addMode(modeNames[i]);
  } else {
    // Reusing an existing collection - make sure every requested mode exists;
    // add any that are missing rather than assuming they're already there.
    const existingModeNames = new Set(collection.modes.map((m) => m.name));
    for (const modeName of modeNames) {
      if (!existingModeNames.has(modeName)) collection.addMode(modeName);
    }
  }
  return collection;
}

async function run() {
  const report = { createdPrimitives: 0, createdSemantics: 0, createdTextStyles: 0, skipped: [] };

  const primitivesCollection = await getOrCreateCollection(TOKENS.primitivesCollectionName, ["Value"]);
  const semanticCollection = await getOrCreateCollection(TOKENS.semanticCollectionName, TOKENS.modes);

  const primModeId = primitivesCollection.modes[0].modeId;
  const semModeIdByName = {};
  semanticCollection.modes.forEach((m) => (semModeIdByName[m.name] = m.modeId));

  const allColorVars = await figma.variables.getLocalVariablesAsync("COLOR");
  const existingPrimByName = {};
  allColorVars
    .filter((v) => v.variableCollectionId === primitivesCollection.id)
    .forEach((v) => (existingPrimByName[v.name] = v));
  const existingSemByName = {};
  allColorVars
    .filter((v) => v.variableCollectionId === semanticCollection.id)
    .forEach((v) => (existingSemByName[v.name] = v));

  // Primitives
  const primVarByName = { ...existingPrimByName };
  for (const [name, hex] of Object.entries(TOKENS.primitives)) {
    if (existingPrimByName[name]) {
      report.skipped.push(`primitive "${name}" already exists - left untouched`);
      continue;
    }
    const v = figma.variables.createVariable(name, primitivesCollection, "COLOR");
    v.scopes = []; // hidden from pickers - only semantics should ever be applied directly
    v.setValueForMode(primModeId, hexToRgb(hex));
    primVarByName[name] = v;
    report.createdPrimitives++;
  }

  // Semantics (aliased to primitives, alias target can vary per mode)
  for (const [name, def] of Object.entries(TOKENS.semantics)) {
    if (existingSemByName[name]) {
      report.skipped.push(`semantic "${name}" already exists - left untouched`);
      continue;
    }
    const v = figma.variables.createVariable(name, semanticCollection, "COLOR");
    v.scopes = scopesForSemantic(name);
    let anySet = false;
    for (const modeName of TOKENS.modes) {
      const targetName =
        typeof def.aliasOf === "string" ? def.aliasOf : def.aliasOf[modeName];
      const target = targetName ? primVarByName[targetName] : undefined;
      const modeId = semModeIdByName[modeName];
      if (target && modeId) {
        v.setValueForMode(modeId, { type: "VARIABLE_ALIAS", id: target.id });
        anySet = true;
      } else {
        report.skipped.push(
          `semantic "${name}" mode "${modeName}" skipped - target primitive "${targetName}" not found`
        );
      }
    }
    if (anySet) report.createdSemantics++;
  }

  // Text styles
  const existingTextStyleNames = new Set(figma.getLocalTextStyles().map((s) => s.name));
  for (const [name, def] of Object.entries(TOKENS.textStyles)) {
    if (existingTextStyleNames.has(name)) {
      report.skipped.push(`text style "${name}" already exists - left untouched`);
      continue;
    }
    await figma.loadFontAsync({ family: def.family, style: def.style });
    const style = figma.createTextStyle();
    style.name = name;
    style.fontName = { family: def.family, style: def.style };
    style.fontSize = def.size;
    if (def.lineHeight) style.lineHeight = { value: def.lineHeight, unit: "PIXELS" };
    if (def.letterSpacing) {
      style.letterSpacing = { value: def.letterSpacing * def.size, unit: "PIXELS" };
    }
    report.createdTextStyles++;
  }

  const summary =
    `Created ${report.createdPrimitives} primitive(s), ${report.createdSemantics} semantic color(s), ` +
    `${report.createdTextStyles} text style(s).` +
    (report.skipped.length ? ` Skipped ${report.skipped.length} - see console for detail.` : "");
  if (report.skipped.length) console.log("figma-design-tokens: skipped", report.skipped);
  figma.closePlugin(summary);
}

run().catch((err) => {
  console.error(err);
  figma.closePlugin(`figma-design-tokens failed: ${err.message}`);
});
